const CHARSET = "qpzry9x8gf2tvdw0s3jn54khce6mua7l";
const GEN = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3];

function polymod(values) {
  let chk = 1;
  for (const v of values) {
    const b = chk >> 25;
    chk = ((chk & 0x1ffffff) << 5) ^ v;
    for (let i = 0; i < 5; i++) if ((b >> i) & 1) chk ^= GEN[i];
  }
  return chk >>> 0;
}
function hrpExpand(hrp) {
  const out = [];
  for (const c of hrp) out.push(c.charCodeAt(0) >> 5);
  out.push(0);
  for (const c of hrp) out.push(c.charCodeAt(0) & 31);
  return out;
}
function createChecksum(hrp, data, constant) {
  const values = hrpExpand(hrp).concat(data, [0, 0, 0, 0, 0, 0]);
  const pm = (polymod(values) ^ constant) >>> 0;
  const out = [];
  for (let i = 0; i < 6; i++) out.push((pm >> (5 * (5 - i))) & 31);
  return out;
}
function bech32Encode(hrp, data, constant = 1) {
  const combined = data.concat(createChecksum(hrp, data, constant));
  return hrp + "1" + combined.map((d) => CHARSET[d]).join("");
}
function convertBits(data, frombits, tobits, pad) {
  let acc = 0, bits = 0;
  const ret = [];
  const maxv = (1 << tobits) - 1;
  for (const value of data) {
    if (value < 0 || value >> frombits) return null;
    acc = (acc << frombits) | value;
    bits += frombits;
    while (bits >= tobits) { bits -= tobits; ret.push((acc >> bits) & maxv); }
  }
  if (pad) { if (bits) ret.push((acc << (tobits - bits)) & maxv); }
  else if (bits >= frombits || ((acc << (tobits - bits)) & maxv)) return null;
  return ret;
}
function encodeSegwit(hrp, witver, witprog, constant) {
  if (constant === undefined) constant = witver === 0 ? 1 : 1; // plain bech32 always
  const conv = convertBits(witprog, 8, 5, true);
  if (conv === null) return null;
  return bech32Encode(hrp, [witver].concat(conv), constant);
}
module.exports = { bech32Encode, encodeSegwit, convertBits, CHARSET, createChecksum, polymod, hrpExpand };

if (require.main === module) {
  const args = process.argv.slice(2);
  const mode = args[0];
  if (mode === "seg") {
    // seg <hrp> <witver> <byte,byte,...> [constant]
    const hrp = args[1];
    const witver = parseInt(args[2], 10);
    const prog = args[3] === "" ? [] : args[3].split(",").map(Number);
    const c = args[4] ? parseInt(args[4], 10) : 1;
    console.log(encodeSegwit(hrp, witver, prog, c));
  } else if (mode === "raw") {
    // raw <hrp> <5bitvals comma sep> [constant]
    const hrp = args[1];
    const data = args[2] === "" ? [] : args[2].split(",").map(Number);
    const c = args[3] ? parseInt(args[3], 10) : 1;
    console.log(bech32Encode(hrp, data, c));
  }
}

