function he(h){const a=[],b=[];for(const ch of h){a.push(ch.charCodeAt(0)>>5);b.push(ch.charCodeAt(0)&31);}return a.concat([0],b);}
function ck(hrp,data,K){const m=(pm(he(hrp).concat(data,[0,0,0,0,0,0]))^K)>>>0;const o=[];for(let i=0;i<6;i++)o.push((m>>(5*(5-i)))&31);return o;}
function enc(hrp,data,K){K=K===undefined?1:K;return hrp+"1"+data.concat(ck(hrp,data,K)).map(d=>CS[d]).join("");}
function cb(data,from,to,pad){let acc=0,bits=0;const r=[],maxv=(1<<to)-1;
 for(const v of data){if(v<0||(v>>from))return null;acc=((acc<<from)|v)>>>0;bits+=from;while(bits>=to){bits-=to;r.push((acc>>bits)&maxv);}}
 if(pad){if(bits)r.push((acc<<(to-bits))&maxv);}else if(bits>=from||((acc<<(to-bits))&maxv))return null;return r;}
function seg(hrp,ver,prog,K){const c=cb(prog,8,5,true);return enc(hrp,[ver].concat(c),K);}
const A=process.argv.slice(2);
if(A[0]==="seg"){const prog=A[3]===""?[]:A[3].split(",").map(Number);process.stdout.write(seg(A[1],parseInt(A[2],10),prog,A[4]!==undefined?parseInt(A[4],10):1)+"\n");}
else if(A[0]==="raw"){const d=A[2]===""?[]:A[2].split(",").map(Number);process.stdout.write(enc(A[1],d,A[3]!==undefined?parseInt(A[3],10):1)+"\n");}
