const CS="qpzry9x8gf2tvdw0s3jn54khce6mua7l";
const G=[0x3b6a57b2,0x26508e6d,0x1ea119fa,0x3d4233dd,0x2a1462b3];
function pm(v){let c=1;for(const d of v){const b=c>>25;c=((c&0x1ffffff)<<5)^d;for(let i=0;i<5;i++)if((b>>i)&1)c^=G[i];}return c>>>0;}
function he(h){const a=[],b=[];for(const ch of h){a.push(ch.charCodeAt(0)>>5);b.push(ch.charCodeAt(0)&31);}return a.concat([0],b);}
function ck(hrp,data,K){const m=(pm(he(hrp).concat(data,[0,0,0,0,0,0]))^K)>>>0;const o=[];for(let i=0;i<6;i++)o.push((m>>(5*(5-i)))&31);return o;}
function enc(hrp,data,K){return hrp+"1"+data.concat(ck(hrp,data,K||1)).map(d=>CS[d]).join("");}
function cb(d,f,t,p){let acc=0,bits=0;const r=[],mx=(1<<t)-1;for(const v of d){acc=((acc<<f)|v)>>>0;bits+=f;while(bits>=t){bits-=t;r.push((acc>>bits)&mx);}}if(p){if(bits)r.push((acc<<(t-bits))&mx);}return r;}
function seg(h,v,p,K){return enc(h,[v].concat(cb(p,8,5,true)),K);}
const hrps=["bc","tb","bcrt","xyz","ltc","tltc","a","abcdefghijklmnop","1","BC","Bc","b1c","x0","zz9"];
let out=[];
let rnd=1234567;
function R(n){rnd=(rnd*1103515245+12345)>>>0;return rnd%n;}
for(let i=0;i<400;i++){
  const hrp=hrps[R(hrps.length)];
  const ver=R(18); // 0..17
  const n=1+R(42); // 1..42
  const prog=[];for(let j=0;j<n;j++)prog.push(R(256));
  const K=R(6)===0?734539939:1;
  let a=seg(hrp,ver,prog,K);
  const m=R(12);
  if(m===0)a=a.toUpperCase();
  else if(m===1)a=a.slice(0,-1)+"q";
  else if(m===2)a=a.replace("1","");
  else if(m===3)a=a+"q";
  else if(m===4)a=a.slice(1);
  const qh=R(3)===0?hrp.toUpperCase():hrp;
  out.push(qh+"\t"+a);
}
process.stdout.write(out.join("\n")+"\n");
